/** UC1-PAUSE-MIRROR + UC1-RESUME-MIRROR tests — TS mirror of hermes
 * `UC1Handoff` (pause beat + resume, `8871dda` + the argv-law fix) riding the
 * consolidated `src/uc1-handoff.ts`.
 *
 * Error reason strings are asserted byte-for-byte (the mirror law); stderr
 * tails that embed host/tool output are prefix-pinned only. The resume
 * valid-snapshot test deep-equals the committed golden fixture
 * `packages/opencode/test/fixtures/uc1-resume-golden.json`, generated by the
 * hermes reference — same fixture, same fields, as the hermes
 * `UC1ResumeGoldenParityTests` (09-plugin-parity.md §4).
 *
 * Fixture discipline: snapshots are built with cwd=repo root and the RELATIVE
 * trace argv `corpus/m1/session-healthy.jsonl` — manifest.yaml/llms.txt embed
 * the trace argv string, so relative keeps artifact bytes host-independent
 * (probed 2026-10-25). Requires the release binaries + the zstd CLI.
 */

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { copyFileSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";

import type { ResumeResult } from "../src/uc1-handoff.ts";
import { resumeVerify, rustBinDir, snapshotDigest, uc1Pause } from "../src/uc1-handoff.ts";

const REPO_ROOT = fileURLToPath(new URL("../../..", import.meta.url));
const ANCHOR = "corpus/m1/session-healthy.jsonl"; // relative argv (fixture discipline)

const GOLDEN_PATH = join(REPO_ROOT, "packages/opencode/test/fixtures/uc1-resume-golden.json");
const GOLDEN = JSON.parse(readFileSync(GOLDEN_PATH, "utf8")) as {
  snapTurn: number;
  verified: boolean;
  reason: string;
  snapshotDigest: string;
  artifactNames: string[];
};

function freshTmp(label: string): string {
  return mkdtempSync(join(tmpdir(), `ctxvm-b3-${label}-`));
}

function baseName(path: string): string {
  const parts = path.split("/");
  return parts[parts.length - 1] ?? path;
}

function sha256(path: string): string {
  return createHash("sha256").update(readFileSync(path)).digest("hex");
}

function buildGoldenSnapshot(dir: string): void {
  const bin = rustBinDir();
  assert.ok(bin, "release binaries not built — run the cargo build gate");
  const proc = spawnSync(
    join(bin, "export"),
    [ANCHOR, "--turn", "0", "--output", dir, "--odps"],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  assert.equal(proc.status, 0, `export failed: ${proc.stderr}`);
}

// ---------------------------------------------------------------------------
// Resume (B3 mirror)
// ---------------------------------------------------------------------------

test("missing dir / empty dir / unparseable turn — reason law byte-for-byte", () => {
  const missing = join(tmpdir(), "ctxvm-b3-nonexistent-resume-snapshot");
  rmSync(missing, { force: true, recursive: true });
  const missingRes: ResumeResult = resumeVerify(missing);
  assert.deepEqual(missingRes, {
    exit_code: 2,
    verified: false,
    reason: `snapshot dir not found: ${missing}`,
    evidence: {},
  });

  const empty = freshTmp("empty");
  assert.deepEqual(resumeVerify(empty), {
    exit_code: 2,
    verified: false,
    reason: `no trace-*.jsonl.zst in ${empty}`,
    evidence: {},
  });

  const badTurn = freshTmp("badturn");
  writeFileSync(join(badTurn, "trace-x.jsonl.zst"), "not a real zstd frame");
  assert.deepEqual(resumeVerify(badTurn), {
    exit_code: 2,
    verified: false,
    reason: "cannot parse turn from trace-x.jsonl.zst",
    evidence: {},
  });
});

test("zstd decompress failure → loud unverified, evidence {turn, snapshot} (prefix pin)", () => {
  const dir = freshTmp("zstdfail");
  writeFileSync(join(dir, "trace-0.jsonl.zst"), "not a real zstd frame");
  const res = resumeVerify(dir);
  assert.equal(res.exit_code, 2);
  assert.equal(res.verified, false);
  assert.match(res.reason, /^zstd decompress failed: /);
  assert.deepEqual(res.evidence, { turn: 0, snapshot: dir });
});

test("replay failure → reason law 'replay exit N: <stderr>' (prefix pin)", () => {
  const dir = freshTmp("replayfail");
  const junk = join(dir, "not-xCABI.jsonl");
  writeFileSync(junk, "this is not xCABI JSONL\n");
  const packed = spawnSync("zstd", ["-f", "-q", junk, "-o", join(dir, "trace-0.jsonl.zst")], {
    encoding: "utf8",
  });
  assert.equal(packed.status, 0, packed.stderr);
  const res = resumeVerify(dir);
  assert.equal(res.verified, false);
  assert.match(res.reason, /^replay exit \d+: /);
  assert.deepEqual(res.evidence, { turn: 0, snapshot: dir });
});

test("valid snapshot → verified; deep-equals the hermes-generated golden fixture", () => {
  const dir = freshTmp("golden");
  buildGoldenSnapshot(dir);
  const res = resumeVerify(dir);
  assert.equal(res.verified, GOLDEN.verified);
  assert.equal(res.exit_code, 0);
  assert.equal(res.reason, GOLDEN.reason);
  const ev = res.evidence;
  assert.equal(ev.snapshot, dir);
  assert.equal(ev.snapshotDigest, GOLDEN.snapshotDigest);
  assert.equal(ev.snapTurn, GOLDEN.snapTurn);
  assert.equal(ev.turn, GOLDEN.snapTurn);
  assert.deepEqual((ev.artifacts ?? []).map(baseName).sort(), GOLDEN.artifactNames);
});

test("snapshotDigest — checksums-hex path and name+bytes fallback mirrored exactly", () => {
  // checksums.sha256 present: hex strings only, sorted by filename.
  const dir = freshTmp("digest");
  writeFileSync(join(dir, "b.artifact"), "B");
  writeFileSync(join(dir, "a.artifact"), "AA");
  writeFileSync(join(dir, "checksums.sha256"), "def0  b.artifact\nabc0  a.artifact\n");
  const h = createHash("sha256");
  h.update("abc0"); // a.artifact first (sorted by name)
  h.update("def0");
  assert.equal(snapshotDigest(dir), "sha256:" + h.digest("hex"));

  // checksums.sha256 absent: sha256 over name||bytes of every other artifact.
  const fallback = freshTmp("digestfallback");
  writeFileSync(join(fallback, "b.bin"), "\x02\x01");
  writeFileSync(join(fallback, "a.bin"), "hello");
  const hf = createHash("sha256");
  hf.update("a.bin");
  hf.update(readFileSync(join(fallback, "a.bin")));
  hf.update("b.bin");
  hf.update(readFileSync(join(fallback, "b.bin")));
  assert.equal(snapshotDigest(fallback), "sha256:" + hf.digest("hex"));
});

// ---------------------------------------------------------------------------
// Pause (B2 mirror + the argv-law fix)
// ---------------------------------------------------------------------------

test("pause argv law: turn rides the documented --turn N flag form", () => {
  // (the hermes bare positional was rejected by the real binary — probe).
  const dir = freshTmp("argvlaw");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "handoff.jsonl"));
  const result = uc1Pause({ traceDir: dir, turn: 2 });
  assert.equal(result.exit_code, 0, `export failed: ${result.stderr}`);
  assert.equal(result.verified, true); // reference dead-path law, disclosed
  const snapshotDir = join(dir, "handoff");
  assert.ok(
    Object.keys(result.snapshot).includes("handoff_dir"),
    "snapshot must carry the dir/label/turn bookkeeping",
  );
  assert.equal(result.snapshot.label, "turn-2");
  assert.equal(result.snapshot.turn, 2);
  // the packaged tree exists and carries all five artifacts
  const packaged = Object.keys(result.report as Record<string, unknown>);
  assert.ok(packaged.includes("artifacts"));
  assert.equal(
    ((result.report as Record<string, unknown>).artifacts as unknown[]).length,
    5,
  );
});

test("pause missing trace → exit 2 'cannot read' (law prefix-pinned)", () => {
  const dir = freshTmp("pmissing");
  const result = uc1Pause({ traceDir: dir });
  assert.equal(result.exit_code, 2);
  assert.match(result.stderr, /cannot read/);
});

test("pause era copies: cp -n never clobbers; snapshot records paths regardless", () => {
  const dir = freshTmp("era");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "base.jsonl"));
  writeFileSync(join(dir, "base.meta.json"), '{"sidecar": true}\n');
  // pre-existing era files must NOT be clobbered (cp -n law)
  writeFileSync(join(dir, "base-flush.jsonl"), "JUNK-ERA");
  writeFileSync(join(dir, "base-flush.meta.json"), "JUNK-META");
  const result = uc1Pause({ traceDir: dir, handoffName: "base" });
  assert.equal(result.exit_code, 0, result.stderr);
  assert.equal(readFileSync(join(dir, "base-flush.jsonl"), "utf8"), "JUNK-ERA");
  assert.equal(readFileSync(join(dir, "base-flush.meta.json"), "utf8"), "JUNK-META");
  // snapshot still records the era paths (reference quirk: records even when
  // the copy was skipped)
  assert.equal(result.snapshot.jsonl, join(dir, "base-flush.jsonl"));
  assert.equal(result.snapshot["meta.json"], join(dir, "base-flush.meta.json"));
  // export ran on the ORIGINAL base (not the junk era)
  const rep = result.report as Record<string, unknown>;
  const snap = rep.snapshot as Record<string, unknown>;
  assert.equal(snap.sourceEvents, 12);
});

test("pause packages byte-identical to a direct export run (design §6 B2 TODO closed)", () => {
  const dir = freshTmp("bytecmp");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "handoff.jsonl"));
  const viaPause = uc1Pause({ traceDir: dir, turn: 2 });
  assert.equal(viaPause.exit_code, 0, viaPause.stderr);
  const directDir = join(dir, "direct");
  const bin = rustBinDir();
  assert.ok(bin);
  const direct = spawnSync(
    join(bin, "export"),
    [join(dir, "handoff.jsonl"), "--turn", "2", "--output", directDir, "--odps"],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  assert.equal(direct.status, 0, direct.stderr);
  const names = readdirSync(join(dir, "handoff")).sort();
  assert.deepEqual(names, readdirSync(directDir).sort());
  for (const name of names) {
    assert.equal(
      sha256(join(dir, "handoff", name)),
      sha256(join(directDir, name)),
      `artifact mismatch: ${name}`,
    );
  }
});

test("pause witness shape: paused_at/turn/handoff_dir + values-order quirk", () => {
  const dir = freshTmp("witness");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "handoff.jsonl"));
  writeFileSync(join(dir, "handoff.meta.json"), "{}\n");
  const result = uc1Pause({ traceDir: dir, turn: 2 });
  const wit = result.witness;
  assert.ok(wit);
  assert.ok(wit.paused_at.endsWith("Z"));
  assert.equal(wit.turn, 2);
  assert.equal(wit.handoff_dir, dir);
  // artifacts = the snapshot dict VALUES in insertion order (reference quirk):
  // era copies first, then the snapshot dir, the label, the turn.
  const arts = wit.artifacts as unknown[];
  assert.equal(arts[0], join(dir, "handoff-turn-2.jsonl"));
  assert.equal(arts[1], join(dir, "handoff-turn-2.meta.json"));
  assert.equal(arts[2], join(dir, "handoff"));
  assert.equal(arts[3], "turn-2");
  assert.equal(arts[4], 2);
});

test("pause name chain: arg > env > 'handoff' (reference OR-chain law)", () => {
  const dir = freshTmp("envchain");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "spot.jsonl"));
  process.env.CTXVM_HANDOFF_NAME = "not-me";
  const argWins = uc1Pause({ traceDir: dir, handoffName: "spot" });
  delete process.env.CTXVM_HANDOFF_NAME;
  assert.equal(argWins.exit_code, 0, argWins.stderr);
  assert.equal(argWins.snapshot.jsonl, join(dir, "spot-flush.jsonl"));

  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "envname.jsonl"));
  process.env.CTXVM_HANDOFF_NAME = "envname";
  const envWins = uc1Pause({ traceDir: dir }); // arg omitted → env wins
  delete process.env.CTXVM_HANDOFF_NAME;
  assert.equal(envWins.exit_code, 0, envWins.stderr);
  assert.equal(envWins.snapshot.jsonl, join(dir, "envname-flush.jsonl"));
});